static int find_current_screen_index(void) {
  if (NUM_SCREENS == 0) return -1; // No scroll sequence
  lv_obj_t* current_screen = lv_scr_act();
  for (int i = 0; i < NUM_SCREENS; i++) {
    lv_obj_t* screen = screen_objects[i]();
    if (screen == current_screen) {
      return i;
    }
  }
  return -1; // Current screen is not in scroll sequence - return invalid index
}

