void nav_go_to_index(int index) {
    if (index >= 0 && index < NUM_SCREENS) {
        stop_delay_timer(); // Stop any active delay timer
        current_screen_index = index;
        lv_obj_t *scr = screen_objects[index]();
        if (scr) {
            lv_disp_load_scr(scr);
            // Check if this screen has a delay connection
            check_and_start_delay_for_screen(index);
        }
    }
}

